function renderComment(list, comment) {
  const li = document.createElement("li");
  const author = document.createElement("a");
  author.textContent = comment.authorName;            // text sink: safe.

  const site = safeHttpUrl(comment.authorWebsite);    // URL sink: validated.
  if (site) author.href = site;

  const body = document.createElement("p");
  body.textContent = comment.text;                     // never innerHTML.
  li.append(author, body);
  list.append(li);
}

function safeHttpUrl(raw) {
  try {
    const url = new URL(raw, location.origin);
    return url.protocol === "https:" || url.protocol === "http:" ? url.href : null;
  } catch {
    return null;
  }
}
```

| Sink | Danger | Safe choice |
|---|---|---|
| `innerHTML`, `insertAdjacentHTML`. | parses markup and event handlers. | `textContent`, createElement. |
| `href`, `src`. | `javascript:` URLs. | `new URL` plus protocol allow-list. |
| `setAttribute(name, ...)` with user name. | `onclick` and similar. | fixed attribute names only. |
| `eval`, `new Function`, `setTimeout("...")`. | runs code. | pass functions, never strings. |

